import{_ as t,o as e,c as d,ai as r}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"C# · 01 语言基础","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/csharp/01-basics.md","filePath":"tech-system/backend/csharp/01-basics.md"}'),c={name:"tech-system/backend/csharp/01-basics.md"};function o(i,a,l,s,n,h){return e(),d("div",null,[...a[0]||(a[0]=[r('<h1 id="c-·-01-语言基础" tabindex="-1">C# · 01 语言基础 <a class="header-anchor" href="#c-·-01-语言基础" aria-label="Permalink to “C# · 01 语言基础”">​</a></h1><blockquote><p>侧翼技能：补 Windows / .NET 与本地中小、工控旁路；<strong>不替代 Java 主栈</strong>。</p></blockquote><h2 id="_1-定位" tabindex="-1">1. 定位 <a class="header-anchor" href="#_1-定位" aria-label="Permalink to “1. 定位”">​</a></h2><ul><li>与 Java 同属 <strong>强类型 OO 企业语言</strong>，有 Java 底子迁移成本低</li><li>绑在 <strong>.NET</strong> 上：Web、桌面、部分工控上位机一条链</li><li>语法比老 Java 更「现代」一点（async、LINQ、属性），本质仍是工程交付</li><li>Windows 生态存量多，洛阳制造向信息化更容易撞上</li></ul><p>一句话：C# 卖的是 <strong>.NET 与 Windows 场景覆盖</strong>，不是换主粮。</p><hr><h2 id="_2-语法与类型-从-java-迁移视角" tabindex="-1">2. 语法与类型（从 Java 迁移视角） <a class="header-anchor" href="#_2-语法与类型-从-java-迁移视角" aria-label="Permalink to “2. 语法与类型（从 Java 迁移视角）”">​</a></h2><table tabindex="0"><thead><tr><th>Java 直觉</th><th>C# 对应</th></tr></thead><tbody><tr><td>class / interface</td><td>基本一致；属性（Property）更常见</td></tr><tr><td>generics</td><td>有；约束语法不同但概念同</td></tr><tr><td>null</td><td>可空引用类型（NRT）建议打开</td></tr><tr><td>stream</td><td>LINQ（<code>Where</code>/<code>Select</code>）</td></tr><tr><td>CompletableFuture</td><td>async/await Task</td></tr><tr><td>package</td><td>namespace + 项目引用</td></tr></tbody></table><h3 id="该熟练的" tabindex="-1">该熟练的 <a class="header-anchor" href="#该熟练的" aria-label="Permalink to “该熟练的”">​</a></h3><ul><li>属性、自动属性、<code>record</code>（DTO）</li><li><code>async</code>/<code>await</code> 与 <code>Task</code>（别同步阻塞 <code>.Result</code> 死锁）</li><li>异常与 <code>using</code> / <code>await using</code> 释放资源</li><li>可空注解：<code>string?</code> 与警告当回事</li></ul><h3 id="集合" tabindex="-1">集合 <a class="header-anchor" href="#集合" aria-label="Permalink to “集合”">​</a></h3><ul><li><code>List&lt;T&gt;</code> / <code>Dictionary&lt;TKey,TValue&gt;</code> / <code>HashSet&lt;T&gt;</code></li><li>LINQ 短查询好用；热点路径注意多次枚举与分配</li></ul><p>下一篇：<a href="./02-core.html">02 核心能力</a></p>',13)])])}const p=t(c,[["render",o]]);export{b as __pageData,p as default};
